.resume-page {
  min-height: 100vh;
  background-color: var(--white);
  color: var(--black);
  padding: 100px var(--side-gap) 60px calc(var(--nav-width) + var(--side-gap));
  font-family: "Space Grotesk", sans-serif;
}

.resume-container {
  max-width: 960px;
  margin: 0 auto;
}

/* Header & Controls */
.resume-top-bar {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 40px;
  padding-bottom: 24px;
  border-bottom: 2px solid var(--black);
}

.resume-title-box h1 {
  font-family: "Clash Display", sans-serif;
  font-size: 42px;
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 6px;
  letter-spacing: -0.5px;
}

.resume-subtitle {
  font-size: 18px;
  font-weight: 600;
  color: var(--secondary);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.resume-actions {
  display: flex;
  gap: 12px;
}

.btn-print {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background-color: var(--black);
  color: var(--white);
  border: 2px solid var(--black);
  padding: 12px 20px;
  font-family: "Space Grotesk", sans-serif;
  font-weight: 700;
  font-size: 14px;
  cursor: pointer;
  border-radius: 4px;
  transition: all 0.2s ease;
}

.btn-print:hover {
  background-color: var(--primary);
  color: var(--black);
  border-color: var(--black);
}

/* Contact Info Section */
.resume-contact-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 20px 40px;
  margin-bottom: 40px;
  background: var(--white);
  border: 1px solid var(--gray-light-2);
  padding: 20px 24px;
  border-radius: 8px;
  box-shadow: 4px 4px 0px var(--black);
}

.contact-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 15px;
}

.contact-item .label {
  font-weight: 700;
  text-transform: uppercase;
  font-size: 12px;
  color: var(--gray-mid);
}

.contact-item a {
  color: var(--black);
  text-decoration: none;
  font-weight: 600;
  border-bottom: 1px solid var(--black);
  transition: color 0.2s ease;
}

.contact-item a:hover {
  color: var(--secondary);
}

/* Content Layout Grid */
.resume-content-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 40px;
}

.resume-section {
  margin-bottom: 40px;
}

.section-title {
  font-family: "Clash Display", sans-serif;
  font-size: 24px;
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 20px;
  padding-bottom: 8px;
  border-bottom: 2px solid var(--primary);
  display: inline-block;
}

.summary-text {
  font-size: 16px;
  line-height: 1.6;
  color: var(--black);
}

/* Experience Items */
.experience-item {
  margin-bottom: 28px;
}

.experience-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 4px;
}

.job-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--black);
}

.job-duration {
  font-size: 13px;
  font-weight: 600;
  color: var(--gray-mid);
}

.job-company {
  font-size: 14px;
  font-weight: 600;
  color: var(--secondary);
  margin-bottom: 12px;
}

.job-details {
  list-style-type: square;
  padding-left: 20px;
  font-size: 15px;
  line-height: 1.6;
}

.job-details li {
  margin-bottom: 6px;
}

/* Skill Groups */
.skill-group {
  margin-bottom: 24px;
}

.skill-group-title {
  font-size: 14px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 10px;
  color: var(--black);
}

.skill-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.skill-tag {
  background-color: var(--gray-light-3);
  color: var(--black);
  padding: 6px 12px;
  font-size: 13px;
  font-weight: 600;
  border-radius: 4px;
  border: 1px solid var(--gray-light-2);
}

.skill-tag.highlight {
  background-color: var(--primary);
  border-color: var(--black);
}

/* Education / Certs */
.edu-item {
  margin-bottom: 16px;
}

.edu-title {
  font-weight: 700;
  font-size: 16px;
}

.edu-sub {
  font-size: 14px;
  color: var(--gray-mid);
}

/* Mobile & Responsive */
@media (max-width: 768px) {
  .resume-page {
    padding: 80px 20px 40px;
  }

  .resume-top-bar {
    flex-direction: column;
    gap: 16px;
  }

  .resume-title-box h1 {
    font-size: 32px;
  }

  .resume-content-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .resume-contact-grid {
    flex-direction: column;
    gap: 12px;
  }
}

/* Print Styles */
@media print {
  .navbar,
  .footer-section,
  .resume-actions,
  .scroll-indicator {
    display: none !important;
  }

  .resume-page {
    padding: 0 !important;
    margin: 0 !important;
    background: white !important;
    color: black !important;
  }

  .resume-container {
    max-width: 100% !important;
  }

  .resume-contact-grid {
    box-shadow: none !important;
    border: 1px solid #ddd !important;
  }

  .btn-print {
    display: none !important;
  }
}

